//! 📝️ Original String projections and numeric UTF8 spans build one final owned String with bounded copies.
use crate::{LayoutMutationSource,LayoutMutationView as LayoutMutation};
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneBinding,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
#[derive(Clone,Copy)]pub struct OriginalTextSpan<'a>{pub source:RetainedCloneRef<'a,String>,pub start:usize,pub end:usize}
pub trait OriginalTextSource{type Mutation:LayoutMutationSource;fn mutation(&self)->RetainedCloneRef<'_,Self::Mutation>;fn baseline(&self)->RetainedCloneRef<'_,LayoutSnapshot>;fn identity(&self)->usize;fn piece_count(&self)->usize;fn piece(&self,index:usize)->OriginalTextSpan<'_>;}
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original text span custody is invalid")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:2048,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=2048;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-2048,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=2048;p}
fn refused(e:ValueError)->ValueError{let p=receipt(e.retained_progress());e.with_retained_progress(p)}
/// 🧳️ Every original span loan and partial final String remains owned until its actual funded transfer or close.
pub struct OriginalTextPreparation{m:Option<RetainedCloneBinding>,b:Option<RetainedCloneBinding>,piece:Option<RetainedCloneBinding>,text:ManuallyDrop<Option<String>>,retirement:RetainedCloneClose,identity:usize,pieces:usize,index:usize,offset:usize,start:usize,end:usize,extent:usize,phase:u8,closing:bool}
impl Default for OriginalTextPreparation{fn default()->Self{Self{m:None,b:None,piece:None,text:ManuallyDrop::new(None),retirement:Default::default(),identity:0,pieces:0,index:0,offset:0,start:0,end:0,extent:0,phase:0,closing:false}}}
impl OriginalTextPreparation{
 pub fn ready(&self)->bool{self.phase==8&&!self.closing}
 fn verify(&self,s:&impl OriginalTextSource)->Result<(),ValueError>{if self.closing{return Err(fault())}s.mutation().check_binding(&self.m)?;s.baseline().check_binding(&self.b)?;if self.phase>=2&&(self.identity!=s.identity()||self.pieces!=s.piece_count()){return Err(fault())}Ok(())}
 fn span<'a>(&self,s:&'a impl OriginalTextSource)->Result<OriginalTextSpan<'a>,ValueError>{let span=s.piece(self.index);let value=span.source.get();if span.start>span.end||span.end>value.len()||!value.is_char_boundary(span.start)||!value.is_char_boundary(span.end){return Err(fault())}if self.piece.is_some(){span.source.check_binding(&self.piece)?;if self.start!=span.start||self.end!=span.end{return Err(fault())}}Ok(span)}
 fn next_end(&self,s:&impl OriginalTextSource)->Result<usize,ValueError>{let span=self.span(s)?;let mut end=self.end.min(self.offset.saturating_add(256));while end>self.offset&&!span.source.get().is_char_boundary(end){end-=1}Ok(end)}
 pub fn demand(&self,s:&impl OriginalTextSource)->Result<RetirementDemand,ValueError>{self.verify(s)?;Ok(match self.phase{0=>nested(s.mutation().binding_demand(&self.m)?.unwrap_or_default()),1=>nested(s.baseline().binding_demand(&self.b)?.unwrap_or_default()),3=>RetirementDemand{capacity_bytes:self.extent,..fixed()},4 if self.index<self.pieces=>nested(self.span(s)?.source.binding_demand(&self.piece)?.unwrap_or_default()),5=>RetirementDemand{copy_bytes:2048+self.next_end(s)?-self.offset,..fixed()},6=>nested(RetainedCloneBinding::close_demand(&self.piece,256)?),_=>fixed()})}
 pub fn advance(&mut self,s:&impl OriginalTextSource,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(s)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};match self.phase{0=>{p=receipt(s.mutation().bind(&mut self.m,child(g)).map_err(refused)?.unwrap_or_default());self.phase=1},1=>{p=receipt(s.baseline().bind(&mut self.b,child(g)).map_err(refused)?.unwrap_or_default());self.identity=s.identity();self.pieces=s.piece_count();self.phase=2},2=>if self.index==self.pieces{self.index=0;self.phase=3}else{let span=self.span(s)?;self.extent=self.extent.checked_add(span.end-span.start).ok_or_else(fault)?;self.index+=1},3=>{self.phase=254;*self.text=Some(String::new());let text=self.text.as_mut().unwrap();let allocation=text.try_reserve_exact(self.extent);p.retained_capacity_bytes=text.capacity();if allocation.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=4},4=>if self.index==self.pieces{self.phase=8}else{let span=self.span(s)?;p=receipt(span.source.bind(&mut self.piece,child(g)).map_err(refused)?.unwrap_or_default());self.start=span.start;self.end=span.end;self.offset=span.start;self.phase=5},5=>{let end=self.next_end(s)?;let span=self.span(s)?;self.text.as_mut().ok_or_else(fault)?.push_str(&span.source.get()[self.offset..end]);self.offset=end;if end==self.end{self.phase=6}},6=>{p=receipt(RetainedCloneBinding::close_one(&mut self.piece,child(g)).map_err(refused)?.progress());if self.piece.is_none(){self.index+=1;self.phase=4}},8=>{},_=>return Err(fault())}Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn take_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<String>>()*2,depth:1,..Default::default()}}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<(Option<String>,RetainedCloneProgress),ValueError>{if !self.ready(){return Err(fault())}let d=self.take_demand();if !retained_clone_grant_admits(g,d){return Ok((None,Default::default()))}self.phase=9;Ok((self.text.take(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(fault())}if self.piece.is_some(){return Ok(nested(RetainedCloneBinding::close_demand(&self.piece,body.min(256))?))}if !self.retirement.is_empty()||self.text.is_some(){return self.retirement.next_owner_demands::<String>(self.text.is_some(),&None,body)}Ok(nested(RetainedCloneBinding::close_demand(if self.b.is_some(){&self.b}else{&self.m},body.min(256))?))}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.piece.is_some(){return RetainedCloneBinding::close_one(&mut self.piece,child(g)).map(|s|RetainedCloneStep::Progress(receipt(s.progress()))).map_err(refused)}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(step)=self.retirement.begin_granted(&mut self.text,g)?{return Ok(RetainedCloneStep::Progress(step.progress()))}let p=receipt(RetainedCloneBinding::close_one(if self.b.is_some(){&mut self.b}else{&mut self.m},child(g)).map_err(refused)?.progress());Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.piece.is_none()&&self.b.is_none()&&self.m.is_none()&&self.text.is_none()&&self.retirement.is_empty()}
}
impl Drop for OriginalTextPreparation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original text spans require funded final-owner cleanup")}}
